/* The caller has an absolute path and the table holds paths
 * relative to the library root, so a key matches when it is a
 * trailing path component run of the argument. Anchoring on the
 * separator is what stops `list.jai` from matching
 * `mylist.jai`. */
const JaiSeedEntry *jaiSeedFind(const char *sourcePath) {
    if (sourcePath == NULL) return NULL;
    size_t pathLen = strlen(sourcePath);
    for (size_t i = 0; i < JAI_SEED_N; i++) {
        size_t keyLen = kSources[i].keyLen;
        if (keyLen > pathLen) continue;
        const char *tail = sourcePath + (pathLen - keyLen);
        if (memcmp(tail, kSources[i].module, keyLen) != 0) continue;
        if (tail != sourcePath && tail[-1] != '/') continue;
        return unpack(i);
    }
    return NULL;
}

size_t jaiSeedCount(void) { return JAI_SEED_N; }

const char *jaiSeedModuleAt(size_t i) {
    return i < JAI_SEED_N ? kSources[i].module : NULL;
}

size_t jaiSeedPeekAt(size_t i, unsigned char *out, size_t n) {
    if (i >= JAI_SEED_N || out == NULL || n == 0) return 0;
    if (n > kSources[i].length) n = kSources[i].length;
    memcpy(out, jaiSeedBlob + kSources[i].offset, n);
    return n;
}
